<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'

import { api, type Regularisation, type RegularisationDetail } from '../api'
import ChoixMois from './ChoixMois.vue'
import { nombreApi, nombreFr } from '../format'

// Mail of a regularisation (SPEC § 8): generated by the server from the frozen amounts, editable here, opened in
// the mail client (never sent automatically). The supporting PDF is downloaded and attached by hand.

const props = defineProps<{ regularisation: Regularisation }>()
defineEmits<{ fermer: [] }>()

const CLE_SIGNATURE = 'colibri.signature'

const detail = ref<RegularisationDetail | null>(null)
const options = reactive({ etalement: 1, provision: '', aPartirDu: '', signature: '' })
const destinataire = ref('')
const objet = ref('')
const corps = ref('')
const erreur = ref<string | null>(null)
const copie = ref(false)

function lireSignature() {
  try {
    return localStorage.getItem(CLE_SIGNATURE) ?? ''
  } catch {
    return ''
  }
}

function retenirSignature() {
  try {
    localStorage.setItem(CLE_SIGNATURE, options.signature)
  } catch {
    // Storage blocked: the signature is simply not remembered
  }
}

onMounted(async () => {
  options.signature = lireSignature()
  try {
    detail.value = await api.regularisation(props.regularisation.id)
    options.provision = nombreFr(detail.value.suggestion.provision_mensuelle)
    options.aPartirDu = detail.value.suggestion.provision_a_partir_du.slice(0, 7)
    await generer()
  } catch (e) {
    erreur.value = (e as Error).message
  }
})

async function generer() {
  retenirSignature()
  try {
    const provision = nombreApi(options.provision)
    const mail = await api.mail(props.regularisation.id, {
      etalement: options.etalement,
      provision_mensuelle: provision,
      provision_a_partir_du: provision && options.aPartirDu ? `${options.aPartirDu}-01` : null,
      signature: options.signature,
    })
    destinataire.value = mail.destinataire ?? ''
    objet.value = mail.objet
    corps.value = mail.corps
    erreur.value = null
  } catch (e) {
    erreur.value = (e as Error).message
  }
}

const mailto = () =>
  `mailto:${encodeURIComponent(destinataire.value)}?subject=${encodeURIComponent(objet.value)}&body=${encodeURIComponent(corps.value)}`

async function copier() {
  await navigator.clipboard.writeText(corps.value)
  copie.value = true
  setTimeout(() => { copie.value = false }, 2000)
}
</script>

<template>
  <section class="detail redaction">
    <h2>
      Mail {{ regularisation.remplace_id ? 'rectificatif' : 'de régularisation' }} – {{ regularisation.locataire }}
      <button type="button" @click="$emit('fermer')">Fermer</button>
    </h2>
    <p v-if="erreur" class="message erreur">{{ erreur }}</p>

    <div class="formulaire">
      <label>Étalement (mensualités)
        <input v-model.number="options.etalement" type="number" min="1" max="24" style="width: 5rem">
      </label>
      <label>Nouvelle provision mensuelle (vide : aucune proposition)
        <input v-model="options.provision" class="nombre" size="8">
      </label>
      <span>À partir de <ChoixMois v-model="options.aPartirDu" /></span>
      <label>Signature <input v-model="options.signature" size="30" placeholder="Votre nom"></label>
      <button type="button" @click="generer">Regénérer le texte</button>
    </div>

    <div class="champs">
      <label>Destinataire <input v-model="destinataire" type="email" size="34" placeholder="adresse du locataire"></label>
      <label style="flex: 1">Objet <input v-model="objet" style="width: 100%"></label>
    </div>
    <textarea v-model="corps" rows="22" class="corps-mail" />

    <div class="actions">
      <a class="bouton principal" :href="mailto()">Ouvrir dans la messagerie</a>
      <button type="button" @click="copier">{{ copie ? 'Copié' : 'Copier le texte' }}</button>
      <a v-if="regularisation.justificatif" class="bouton" :href="api.justificatifUrl(regularisation.id)" target="_blank">
        Télécharger le justificatif PDF
      </a>
      <span class="discret">Le justificatif est à joindre au message ; rien n'est envoyé automatiquement.</span>
    </div>
  </section>
</template>
